window.AUTH=window.AUTH||{};window.AUTH["19-357"]={"d":"19-357","id":"2020/19-357","n":"City of Chicago v. Fulton","briefs":[{"k":"petitioner","label":"Brief of petitioner City of Chicago","date":"2020-02-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-357/130839/20200203181707459_19-357%20ts.pdf","side":"pet","n":42},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-02-10","url":"https://www.supremecourt.gov/DocketPDF/19/19-357/132572/20200210171709476_19-357tsacUnitedStates.pdf","side":"us","n":61},{"k":"respondent","label":"Brief of respondents Robbin L. Fulton, et al.","date":"2020-03-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-357/135048/20200310091403742_19-357%20bs%20main.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner City of Chicago","date":"2020-04-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-357/141179/20200408152619860_19-357%20rb.pdf","side":"pet","n":11}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-357_6k47.pdf","tr":true,"items":[{"t":"case","label":"Bullard v. Blue Hills Bank","cite":"135 S. Ct. 1686","y":2015,"id":"2014/14-116","sc":1,"by":{"0":"7"}},{"t":"case","label":"Checkers Drive-In Restaurants, Inc. v. Commissioner of Patents & Trademarks","cite":"51 F.3d 1078","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/51/1078/","by":{"0":"22, 23"},"q":[{"src":"brief","b":0,"text":"make[s] sure that creditors do not destroy the bankrupt estate in their scramble for relief.","cite":"51 F.3d at 1082"}]},{"t":"case","label":"Citizens Bank of Maryland v. Strumpf","cite":"516 U.S. 16","y":1995,"id":"1995/94-1340","sc":1,"by":{"0":"16, 42, 43","1":"20","2":"2, 50, 51, 52","3":"6, 7, 20"},"q":[{"src":"brief","b":2,"text":"[i]t would be an odd construction of § 362(a)(7) that required a creditor with a right of setoff to do immediately that which §542(b) specifically excuses it from doing as a general matter: pay a claim to which a defense of setoff applies.","cite":"516 U.S. at 20"},{"src":"brief","b":3,"text":"It is an elementary rule of construction that ‘the act cannot be held to destroy itself.’","cite":"516 U.S. 16, 20"}]},{"t":"case","label":"City of Chicago v. Kennedy","cite":"2018 WL 2087453","y":2018,"court":"N.D. Ill. May 4","by":{"0":"14","3":"21, 22"}},{"t":"case","label":"City of Springfield v. Kibbe","cite":"480 U.S. 257","y":1987,"id":"1986/85-1217","sc":1,"by":{"0":"14"}},{"t":"case","label":"Cohen v. de la Cruz","cite":"523 U.S. 213","y":1998,"id":"1997/96-1923","sc":1,"by":{"0":"4, 28, 29","1":"23","3":"13"},"q":[{"src":"brief","b":0,"text":"will not read the Bankruptcy Code to erode past bankruptcy practice absent a clear indication that Congress intended such a departure.","cite":"523 U.S. 213, 221"},{"src":"brief","b":3,"text":"will not read the Bankruptcy Code to erode past bankruptcy practice absent a clear indica- 3 The single case Debtors cite (Br. 32) is not to the contrary. The entity in possession was not a secured creditor seeking adequate protection, and it asserted no statutory defense to turnover. In re Larimer, 27 B.R. 514, 516 (Bankr. D. Idaho 1983). tion that Congress intended such a departure.","cite":"523 U.S. 213, 221"}]},{"t":"case","label":"Continental National Bank & Trust Co. v. Chicago, Rock Island & Pacific Railwy Co.","cite":"294 U.S. 648","y":1935,"id":"scdb/1934-088","sc":1,"by":{"0":"25"},"q":[{"src":"argument","who":"Mr. Goldblatt","text":"That's the construction of the automatic stay that this Court has given in cases going back to Continental Illinois in 1935 and running through Ritzen and Taggart in the last few terms."}]},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"0":"29"}},{"t":"case","label":"Hall v. United States","cite":"566 U.S. 506","y":2012,"id":"2011/10-875","sc":1,"by":{"0":"28"}},{"t":"case","label":"Hamilton v. Lanning","cite":"560 U.S. 505","y":2010,"id":"2009/08-998","sc":1,"by":{"0":"18, 28"}},{"t":"case","label":"Hillis Motors, Inc. v. Hawaii Automobile Dealers’ Ass’n","cite":"997 F.2d 581","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/997/581/","by":{"0":"22, 31"},"q":[{"src":"brief","b":0,"text":"effect[ing] an immediate freeze of the status quo.","cite":"997 F.2d 581, 585"}]},{"t":"case","label":"ICC v. Holmes Transportation, Inc.","cite":"931 F.2d 984","y":1991,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/931/984/","by":{"0":"22"}},{"t":"case","label":"International Union v. Bagwell","cite":"512 U.S. 821","y":1994,"id":"1993/92-1625","sc":1,"by":{"0":"38"}},{"t":"case","label":"Kissinger v. Reporters Committee for Freedom of the Press","cite":"45 U.S. 136","y":1980,"id":"1979/78-1088","sc":1,"by":{"0":"38"}},{"t":"case","label":"Maggio v. Zeitz","cite":"333 U.S. 56","y":1948,"id":"scdb/1947-035","sc":1,"by":{"0":"40","1":"4, 23"}},{"t":"case","label":"Marlyn Nutraceuticals, Inc. v. Mucos Pharma GmbH & Co.","cite":"571 F.3d 873","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/571/873/","by":{"0":"19"}},{"t":"case","label":"Meghrig v. KFC Western, Inc.","cite":"516 U.S. 479","y":1996,"id":"1995/95-83","sc":1,"by":{"0":"19"}},{"t":"case","label":"Mission Product Holdings, Inc. v. Tempnology, LLC","cite":"139 S. Ct. 1652","y":2019,"id":"2018/17-1657","sc":1,"by":{"0":"23, 25, 36, 44","1":"12","2":"49, 50","3":"11"},"q":[{"src":"brief","b":0,"text":"[t]he estate cannot possess anything more than the debtor itself did outside bankruptcy.","cite":"139 S. Ct. 1652, 1663"}]},{"t":"case","label":"National Federation of Independent Business v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"20"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"0":"19, 20","1":"14, 15","2":"27, 28","3":"8, 10"},"q":[{"src":"brief","b":1,"text":"‘simply suspend[s] judicial alteration of the status quo.’","cite":"556 U.S. 418, 429"},{"src":"brief","b":3,"text":"preventing some action before [its] legality … has been conclusively determined.","cite":"556 U.S. 418, 428429"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"suspend[s] judicial alteration of the status quo.","cite":"556 U. S. 418, 429"}]},{"t":"case","label":"North American Soccer League, LLC v. United States Soccer Federation, Inc.","cite":"883 F.3d 32","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/883/32/","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"[p]rohibitory injunctions maintain the status quo pending resolution of the case; mandatory injunctions alter it.","cite":"883 F.3d 32, 36"}]},{"t":"case","label":"Pennsylvania Department of Public Welfare v. Davenport","cite":"495 U.S. 552","y":1990,"id":"1989/89-156","sc":1,"by":{"0":"35"}},{"t":"case","label":"Reconstruction Finance Corp. v. Kaplan","cite":"185 F.2d 791","y":1950,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/185/791/","by":{"0":"40","3":"19"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"0":"20","2":"2, 3, 18"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"by":{"0":"10, 21, 38","2":"40","3":"16"},"q":[{"src":"brief","b":2,"text":"chief purpose of the bankruptcy laws’: ‘to secure a prompt and effectual’ resolution of bankruptcy cases ‘within a limited period.’","cite":"139 S. Ct. 1795, 1803"},{"src":"argument","who":"Mr. Goldblatt","text":"That's the construction of the automatic stay that this Court has given in cases going back to Continental Illinois in 1935 and running through Ritzen and Taggart in the last few terms."},{"src":"argument","who":"Mr. Goldblatt","text":"And, Justice Breyer, as you wrote for a unanimous court just 16 months ago in the Taggart case, where there is a -- even -- even in the discharge injunction context, where the statute does use injunctive language, where there is fair ground of doubt, a -- a court will not resort to contempt to punish a party that exercises its rights in a position where -- where it's taking positions in good faith."},{"src":"argument","who":"Mr. Goldblatt","text":"So, Justice Gorsuch, we think that the answer to that question is provided by the unanimous opinion of this Court in Taggart just -- just 16 months ago, where the Court said that the -- the -- the discharge injunction, which is a statutory provision of the Bankruptcy Code that has injunctive language, unlike 542, that where there is fair ground of doubt about whether the action was a violation, that contempt authority is not available."}]},{"t":"case","label":"Thompson v. General Motors Acceptance Corp.","cite":"566 F.3d 699","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/566/699/","by":{"0":"11, 14, 17, 18, 27, 37","1":"6","2":"3, 19, 33"},"q":[{"src":"brief","b":0,"text":"[h]olding onto an asset [and] refusing to return it","cite":"566 F.3d at 702"},{"src":"brief","b":1,"text":"ignore[d] the purpose of bankruptcy—‘to allow the debtor to regain his financial foothold and repay his creditors.’","cite":"566 F.3d at 706"},{"src":"brief","b":2,"text":"[h]olding onto an asset, refusing to return it, and otherwise prohibiting a debtor’s beneficial use of an asset.","cite":"566 F.3d 699, 702"},{"src":"brief","b":2,"text":"[T]he mere fact that [in 1984] Congress expanded the provision to prohibit conduct above and beyond obtaining possession of an asset suggests that it intended to include conduct by creditors who seized an asset pre-petition.","cite":"566 F.3d at 702"}]},{"t":"case","label":"Travelers Casualty & Surety Co. of America v. Pacific Gas & Electric Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"by":{"0":"28","2":"38"}},{"t":"case","label":"U.S. Department of Justice v. Tax Analysis","cite":"492 U.S. 136","y":1989,"id":"1988/88-782","sc":1,"by":{"0":"38"},"q":[{"src":"argument","who":"Mr. Goldblatt","text":"Chief Justice, and may it please the Court: This case presents the question whether the Bankruptcy Code's automatic stay requires a creditor in lawful possession of estate property when a bankruptcy petition is filed to return that property to the debtor immediately or else pay damages."},{"src":"argument","who":"Mr. Goldblatt","text":"Chief Justice, we don't -- we don't intend to -- our position doesn't turn on a fine distinction between action and inaction. Our fundamental position is that the entire statutory phrase \"acts to exercise control\" is a prohibition on actions that change the status quo."},{"src":"argument","who":"Chief Justice Roberts","text":"Thank you, counsel. Justice Thomas."}]},{"t":"case","label":"United Savings Ass’n v. Timbers of Inwood Forest Associates, Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"by":{"0":"36"}},{"t":"case","label":"United States v. Inslaw, Inc.","cite":"932 F.2d 1467","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/932/1467/","by":{"0":"9, 21, 24","1":"7, 15"},"q":[{"src":"brief","b":0,"text":"The automatic stay … serves as a restraint only on acts to gain possession or control over property of the estate.","cite":"932 F.2d at 1474"},{"src":"argument","who":"Mr. Goldblatt","text":"Circuit's decision in Inslaw. The critical language is there on page 1473 of Volume 932 of F.2d. There, Judge Stephen Williams made three points."}]},{"t":"case","label":"United States v. Ron Pair Enterprises","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"by":{"0":"17","2":"1"},"q":[{"src":"brief","b":0,"text":"begin[] with the language of the statute itself.","cite":"489 U.S. 235, 241"}]},{"t":"case","label":"United States v. Whiting Pools, Inc.","cite":"462 U.S. 198","y":1983,"id":"1982/82-215","sc":1,"by":{"0":"passim","1":"24, 29","2":"passim","3":"11, 17, 18, 19"},"q":[{"src":"brief","b":0,"text":"[a]t the secured creditor’s insistence, the bankruptcy court must place such limits or conditions on the trustee’s power to sell, use, or lease property as are necessary to protect the creditor.","cite":"462 U.S. at 204"},{"src":"brief","b":0,"text":"explicit limitations on the reach of § 542(a).","cite":"462 U.S. at 206"},{"src":"brief","b":1,"text":"grants to the [bankruptcy] estate a possessory interest in certain property of the debtor that was not held by the debtor at the commencement of reorganization proceedings.","cite":"462 U.S. at 207"},{"src":"brief","b":1,"text":"need for a [Bankruptcy Code] provision authorizing the turnover of property of the debtor in the possession of secured creditors.","cite":"462 U.S. at 207"},{"src":"brief","b":2,"text":"includes property of the debtor that has been seized by a creditor prior to the filing of a petition for reorganization.","cite":"462 U.S. at 209"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"is intended to include in the estate any property made available to the estate by other provisions of the Bankruptcy Code.","cite":"462 U. S. 198, 205"},{"src":"opinion","who":"Justice Sotomayor, concurring","text":"adequate protection [to] replace the protection afforded by possession.","cite":"462 U. S. 198, 207"}]},{"t":"case","label":"United States v. Whiting Pools, Inc.","cite":"674 F.2d 144","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/674/144/","by":{"0":"41","2":"4, 49"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","by":{"0":"38"}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","subs":["(a)"],"stext":{"head":"§105. Power of court","paras":[[0,"(a) The court may issue any order, process, or judgment that is necessary or appropriate to carry out the provisions of this title. No provision of this title providing for the raising of an issue by a party in interest shall be construed to preclude the court from, sua sponte, taking any action or making any determination necessary or appropriate to enforce or implement court orders or rules, or to prevent an abuse of process."],[0,"(b) Notwithstanding subsection (a) of this section, a court may not appoint a receiver in a case under this title."],[0,"(c) The ability of any district judge or other officer or employee of a district court to exercise any of the authority or responsibilities conferred upon the court under this title shall be determined by reference to the provisions relating to such judge, officer, or employee set forth in title 28. This subsection shall not be interpreted to exclude bankruptcy judges and other officers or employees appointed pursuant to chapter 6 of title 28 from its operation."],[0,"(d) The court, on its own motion or on the request of a party in interest—"],[1,"(1) shall hold such status conferences as are necessary to further the expeditious and economical resolution of the case; and"],[1,"(2) unless inconsistent with another provision of this title or with applicable Federal Rules of Bankruptcy Procedure, may issue an order at any such conference prescribing such limitations and conditions as the court deems appropriate to ensure that the case is handled expeditiously and economically, including an order that—"],[2,"(A) sets the date by which the trustee must assume or reject an executory contract or unexpired lease; or"],[2,"(B) in a case under chapter 11 of this title—"],[3,"(i) sets a date by which the debtor, or trustee if one has been appointed, shall file a disclosure statement and plan;"],[3,"(ii) sets a date by which the debtor, or trustee if one has been appointed, shall solicit acceptances of a plan;"],[3,"(iii) sets the date by which a party in interest other than a debtor may file a plan;"],[3,"(iv) sets a date by which a proponent of a plan, other than the debtor, shall solicit acceptances of such plan;"],[3,"(v) fixes the scope and format of the notice to be provided regarding the hearing on approval of the disclosure statement; or"],[3,"(vi) provides that the hearing on approval of the disclosure statement may be combined with the hearing on confirmation of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/105?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 37","1":"4, 23","3":"5, 16"},"q":[{"src":"brief","b":1,"text":"issue any order, process, or judgment that is necessary or appropriate to carry out the provisions of this title.","cite":"11 U.S.C. 105(a)"}]},{"t":"usc","label":"15 U.S.C. § 8306","url":"https://www.law.cornell.edu/uscode/text/15/8306","by":{"0":"39"}},{"t":"usc","label":"18 U.S.C. § 3626","url":"https://www.law.cornell.edu/uscode/text/18/3626","by":{"0":"39"}},{"t":"usc","label":"27 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/27/204","by":{"0":"39"}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","by":{"0":"39"}},{"t":"usc","label":"42 U.S.C. § 6972","url":"https://www.law.cornell.edu/uscode/text/42/6972","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"mandatory injunction, i.e., one that orders a responsible party to ‘take action’ by attending to the cleanup … of toxic waste, or a prohibitory injunction, i.e., one that ‘restrains’ a responsible party from further violating [the statute]","cite":"42 U.S.C. § 6972(a)(1)(B)"}]},{"t":"law","label":"Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/2549","by":{"0":"26","1":"28"}},{"t":"law","label":"Pub. L. No. 98-353","url":"https://www.govinfo.gov/link/statute/98/333","by":{"0":"27, 39","1":"28","2":"32"}},{"t":"case","label":"California Emp’t Dev. Dep’t v. Taxel (In re Del Mission Ltd.)","cite":"98 F.3d 1147","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/98/1147/","by":{"1":"7"}},{"t":"case","label":"Chambers v. NASCO, Inc.","cite":"501 U.S. 32","y":1991,"id":"1990/90-256","sc":1,"by":{"1":"32"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"by":{"1":"19, 20"}},{"t":"case","label":"Fitzgerald v. United States ex rel. IRS (In re Larimer)","cite":"27 B.R. 514","y":1983,"court":"Bankr. D. Idaho","url":"https://www.courtlistener.com/c/B.R./27/514/","by":{"1":"32"}},{"t":"case","label":"Gharib v. Casey (In re Kenny G Enters., LLC )","cite":"692 Fed. Appx. 950","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./692/950/","by":{"1":"24"}},{"t":"case","label":"Knaus v. Concordia Lumber Co. (In re Knaus)","cite":"889 F.2d 773","y":1989,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/889/773/","by":{"1":"7"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"1":"19"}},{"t":"case","label":"Motors Acceptance Corp. v. Rozier (In re Rozier)","cite":"376 F.3d 1323","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1323/","by":{"1":"7"}},{"t":"case","label":"National Ass’n of Home Builders v. Defenders of Wildlife","cite":"551 U.S. 644","y":2007,"id":"2006/06-340","sc":1,"by":{"1":"13","2":"2, 18, 20"},"q":[{"src":"brief","b":1,"text":"It is a fundamental canon of statutory construction that the words of a statute must be read in their context and with a view to their place in the overall statutory scheme.","cite":"551 U.S. 644, 666"},{"src":"brief","b":2,"text":"fundamental canon of statutory construction that the words of a statute must be read in their context and with a view to their place in the overall statutory scheme.","cite":"551 U.S. at 666"},{"src":"brief","b":2,"text":"their place in the overall statutory scheme.","cite":"551 U.S. at 666"}]},{"t":"case","label":"Ohio Citizens for Responsible Energy, Inc. v. NRC","cite":"479 U.S. 1312","y":1986,"url":"https://supreme.justia.com/cases/federal/us/479/1312/","sc":1,"by":{"1":"14"}},{"t":"case","label":"Oriel v. Russell","cite":"278 U.S. 358","y":1929,"id":"scdb/1928-076","sc":1,"by":{"1":"4, 23"}},{"t":"case","label":"Robb v. Sowers (In re Sowers)","cite":"97 B.R. 480","y":1989,"court":"Bankr. N.D. Ind.","url":"https://www.courtlistener.com/c/B.R./97/480/","by":{"1":"24"}},{"t":"case","label":"Schreiber v. Burlington N., Inc.","cite":"472 U.S. 1","y":1985,"id":"1984/83-2129","sc":1,"by":{"1":"16, 17"},"q":[{"src":"brief","b":1,"text":"[I]t is a ‘familiar principle of statutory construction that words grouped in a list should be given related meaning.’","cite":"472 U.S. 1, 8"}]},{"t":"case","label":"Securities Indus. Ass’n v. Board of Governors of the Fed. Reserve Sys.","cite":"468 U.S. 207","y":1984,"id":"1983/83-614","sc":1,"by":{"1":"16"}},{"t":"case","label":"United States v. Sanchez DeFundora","cite":"893 F.2d 1173","y":1990,"url":"https://www.courtlistener.com/c/F.2d/893/1173/","by":{"1":"21"}},{"t":"case","label":"WD Equip., LLC v. Cowen (In re Cowen)","cite":"849 F.3d 943","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/849/943/","by":{"1":"7, 15, 16, 22, 32"},"q":[{"src":"brief","b":1,"text":"commonly means to ‘take action’ or ‘do something.’","cite":"849 F.3d at 949"},{"src":"brief","b":1,"text":"act to * * * exercise control over","cite":"849 F.3d at 949"}]},{"t":"case","label":"Weber v. SEFCU (In re Weber)","cite":"719 F.3d 72","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/719/72/","by":{"1":"7"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","by":{"1":"2, 4, 23"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"1":"25"}},{"t":"usc","label":"11 U.S.C. § 342","url":"https://www.law.cornell.edu/uscode/text/11/342","subs":["(g)","(g)(2)","(b)"],"stext":{"head":"§342. Notice","paras":[[0,"(a) There shall be given such notice as is appropriate, including notice to any holder of a community claim, of an order for relief in a case under this title."],[0,"(b) Before the commencement of a case under this title by an individual whose debts are primarily consumer debts, the clerk shall give to such individual written notice containing—"],[1,"(1) a brief description of—"],[2,"(A) chapters 7, 11, 12, and 13 and the general purpose, benefits, and costs of proceeding under each of those chapters; and"],[2,"(B) the types of services available from credit counseling agencies; and"],[1,"(2) statements specifying that—"],[2,"(A) a person who knowingly and fraudulently conceals assets or makes a false oath or statement under penalty of perjury in connection with a case under this title shall be subject to fine, imprisonment, or both; and"],[2,"(B) all information supplied by a debtor in connection with a case under this title is subject to examination by the Attorney General."],[0,"(c)(1) If notice is required to be given by the debtor to a creditor under this title, any rule, any applicable law, or any order of the court, such notice shall contain the name, address, and last 4 digits of the taxpayer identification number of the debtor. If the notice concerns an amendment that adds a creditor to the schedules of assets and liabilities, the debtor shall include the full taxpayer identification number in the notice sent to that creditor, but the debtor shall include only the last 4 digits of the taxpayer identification number in the copy of the notice filed with the court."],[0,"(2)(A) If, within the 90 days before the commencement of a voluntary case, a creditor supplies the debtor in at least 2 communications sent to the debtor with the current account number of the debtor and the address at which such creditor requests to receive correspondence, then any notice required by this title to be sent by the debtor to such creditor shall be sent to such address and shall include such account number."],[0,"(B) If a creditor would be in violation of applicable nonbankruptcy law by sending any such communication within such 90-day period and if such creditor supplies the debtor in the last 2 communications with the current account number of the debtor and the address at which such creditor requests to receive correspondence, then any notice required by this title to be sent by the debtor to such creditor shall be sent to such address and shall include such account number."],[0,"(d) In a case under chapter 7 of this title in which the debtor is an individual and in which the presumption of abuse arises under section 707(b), the clerk shall give written notice to all creditors not later than 10 days after the date of the filing of the petition that the presumption of abuse has arisen."],[0,"(e)(1) In a case under chapter 7 or 13 of this title of a debtor who is an individual, a creditor at any time may both file with the court and serve on the debtor a notice of address to be used to provide notice in such case to such creditor."],[0,"(2) Any notice in such case required to be provided to such creditor by the debtor or the court later than 7 days after the court and the debtor receive such creditor's notice of address, shall be provided to such address."],[0,"(f)(1) An entity may file with any bankruptcy court a notice of address to be used by all the bankruptcy courts or by particular bankruptcy courts, as so specified by such entity at the time such notice is filed, to provide notice to such entity in all cases under chapters 7 and 13 pending in the courts with respect to which such notice is filed, in which such entity is a creditor."],[0,"(2) In any case filed under chapter 7 or 13, any notice required to be provided by a court with respect to which a notice is filed under paragraph (1), to such entity later than 30 days after the filing of such notice under paragraph (1) shall be provided to such address unless with respect to a particular case a different address is specified in a notice filed and served in accordance with subsection (e)."],[0,"(3) A notice filed under paragraph (1) may be withdrawn by such entity."],[0,"(g)(1) Notice provided to a creditor by the debtor or the court other than in accordance with this section (excluding this subsection) shall not be effective notice until such notice is brought to the attention of such creditor. If such creditor designates a person or an organizational subdivision of such creditor to be responsible for receiving notices under this title and establishes reasonable procedures so that such notices receivable by such creditor are to be delivered to such person or such subdivision, then a notice provided to such creditor other than in accordance with this section (excluding this subsection) shall not be considered to have been brought to the attention of such creditor until such notice is received by such person or such subdivision."],[0,"(2) A monetary penalty may not be imposed on a creditor for a violation of a stay in effect under section 362(a) (including a monetary penalty imposed under section 362(k)) or for failure to comply with section 542 or 543 unless the conduct that is the basis of such violation or of such failure occurs after such creditor receives notice effective under this section of the order for relief."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/342?type=usc&year=mostrecent&link-type=html"},"by":{"1":"25, 25","2":"39"},"q":[{"src":"brief","b":1,"text":"[a] monetary penalty may not be imposed on a creditor for a violation of a stay in effect under section 362(a) (including a monetary penalty imposed under section 362(k)) or for failure to comply with section 542 or 543 unless the conduct that is the basis of such violation or of such failure occurs after such creditor receives notice effective under this section of the order for relief.","cite":"11 U.S.C. 342(g)(2)"}]},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(a)(1988)","(a)","(a)(1)","(a)(2)","(a)(3)","(a)(4)","(a)(6)","(a)(8)","(c)","(k)","(k)(1)","(d)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"by":{"1":"20, 20, 19, 22, 19, 22, 19, 22, 19, 22, 19, 22, 19, 22, 19, 22, 19, 22, 19, 22, 19, 22","2":"17, 18, 22, 6, 46"},"q":[{"src":"brief","b":1,"text":"any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate.","cite":"11 U.S.C. 362(a)(3)"},{"src":"brief","b":1,"text":"an individual injured by any willful violation of a stay provided by this section shall recover actual damages, including costs and attorneys’ fees, and, in appropriate circumstances, may recover punitive damages.","cite":"11 U.S.C. 362(k)(1)"},{"src":"brief","b":2,"text":"stay[s]…any act to obtain possession of property of the estate or…to exercise control over property of the estate.","cite":"11 U.S.C. §362(a)(3)"},{"src":"brief","b":2,"text":"any act...to exercise control over property of the estate.","cite":"11 U.S.C. §362(a)(3)"},{"src":"opinion","who":"Opinion of the Court (Justice Alito)","text":"any act . . . to exercise control over property","cite":"11 U. S. C. §362(a)(3)"},{"src":"opinion","who":"Justice Sotomayor, concurring","text":"any act . . . to exercise control over property of the [bankruptcy] estate.","cite":"11 U. S. C. §362(a)(3)"},{"src":"argument","who":"Mr. Goldblatt","text":"We think that the analysis is that what Section 362, the automatic stay, does is preserve the status quo. Now, to be sure, the consolidation or marshaling of assets of the estate is work to be done in a bankruptcy case."},{"src":"argument","who":"Mr. Goldblatt","text":"And the question presented by this case is whether Section 362, the automatic stay, essentially allows an end run around all of that, avoiding those questions, skipping over the defenses, and providing an automatic claim for damages, attorneys' fees, and, in some cases, punitive damages."},{"src":"argument","who":"Ms. Sinzdak","text":"First, Section 362 imposes a stay, and the term \"stay\" denotes a command to preserve the status quo. Section 362(a)(3), therefore, cannot be read to compel a creditor to alter the status quo."}]},{"t":"usc","label":"11 U.S.C. § 363","url":"https://www.law.cornell.edu/uscode/text/11/363","subs":["(c)(2)","(e)","(b)","(c)"],"stext":{"head":"§363. Use, sale, or lease of property","paras":[[0,"(a) In this section, \"cash collateral\" means cash, negotiable instruments, documents of title, securities, deposit accounts, or other cash equivalents whenever acquired in which the estate and an entity other than the estate have an interest and includes the proceeds, products, offspring, rents, or profits of property and the fees, charges, accounts or other payments for the use or occupancy of rooms and other public facilities in hotels, motels, or other lodging properties subject to a security interest as provided in section 552(b) of this title, whether existing before or after the commencement of a case under this title."],[0,"(b)(1) The trustee, after notice and a hearing, may use, sell, or lease, other than in the ordinary course of business, property of the estate, except that if the debtor in connection with offering a product or a service discloses to an individual a policy prohibiting the transfer of personally identifiable information about individuals to persons that are not affiliated with the debtor and if such policy is in effect on the date of the commencement of the case, then the trustee may not sell or lease personally identifiable information to any person unless—"],[1,"(A) such sale or such lease is consistent with such policy; or"],[1,"(B) after appointment of a consumer privacy ombudsman in accordance with section 332, and after notice and a hearing, the court approves such sale or such lease—"],[2,"(i) giving due consideration to the facts, circumstances, and conditions of such sale or such lease; and"],[2,"(ii) finding that no showing was made that such sale or such lease would violate applicable nonbankruptcy law."],[0,"(2) If notification is required under subsection (a) of section 7A of the Clayton Act in the case of a transaction under this subsection, then—"],[1,"(A) notwithstanding subsection (a) of such section, the notification required by such subsection to be given by the debtor shall be given by the trustee; and"],[1,"(B) notwithstanding subsection (b) of such section, the required waiting period shall end on the 15th day after the date of the receipt, by the Federal Trade Commission and the Assistant Attorney General in charge of the Antitrust Division of the Department of Justice, of the notification required under such subsection (a), unless such waiting period is extended—"],[2,"(i) pursuant to subsection (e)(2) of such section, in the same manner as such subsection (e)(2) applies to a cash tender offer;"],[2,"(ii) pursuant to subsection (g)(2) of such section; or"],[2,"(iii) by the court after notice and a hearing."],[0,"(c)(1) If the business of the debtor is authorized to be operated under section 721, 1108, 1183, 1184, 1203, 1204, or 1304 of this title and unless the court orders otherwise, the trustee may enter into transactions, including the sale or lease of property of the estate, in the ordinary course of business, without notice or a hearing, and may use property of the estate in the ordinary course of business without notice or a hearing."],[0,"(2) The trustee may not use, sell, or lease cash collateral under paragraph (1) of this subsection unless—"],[1,"(A) each entity that has an interest in such cash collateral consents; or"],[1,"(B) the court, after notice and a hearing, authorizes such use, sale, or lease in accordance with the provisions of this section."],[0,"(3) Any hearing under paragraph (2)(B) of this subsection may be a preliminary hearing or may be consolidated with a hearing under subsection (e) of this section, but shall be scheduled in accordance with the needs of the debtor. If the hearing under paragraph (2)(B) of this subsection is a preliminary hearing, the court may authorize such use, sale, or lease only if there is a reasonable likelihood that the trustee will prevail at the final hearing under subsection (e) of this section. The court shall act promptly on any request for authorization under paragraph (2)(B) of this subsection."],[0,"(4) Except as provided in paragraph (2) of this subsection, the trustee shall segregate and account for any cash collateral in the trustee's possession, custody, or control."],[0,"(d) The trustee may use, sell, or lease property under subsection (b) or (c) of this section—"],[1,"(1) in the case of a debtor that is a corporation or trust that is not a moneyed business, commercial corporation, or trust, only in accordance with nonbankruptcy law applicable to the transfer of property by a debtor that is such a corporation or trust; and"],[1,"(2) only to the extent not inconsistent with any relief granted under subsection (c), (d), (e), or (f) of section 362."],[0,"(e) Notwithstanding any other provision of this section, at any time, on request of an entity that has an interest in property used, sold, or leased, or proposed to be used, sold, or leased, by the trustee, the court, with or without a hearing, shall prohibit or condition such use, sale, or lease as is necessary to provide adequate protection of such interest. This subsection also applies to property that is subject to any unexpired lease of personal property (to the exclusion of such property being subject to an order to grant relief from the stay under section 362)."],[0,"(f) The trustee may sell property under subsection (b) or (c) of this section free and clear of any interest in such property of an entity other than the estate, only if—"],[1,"(1) applicable nonbankruptcy law permits sale of such property free and clear of such interest;"],[1,"(2) such entity consents;"],[1,"(3) such interest is a lien and the price at which such property is to be sold is greater than the aggregate value of all liens on such property;"],[1,"(4) such interest is in bona fide dispute; or"],[1,"(5) such entity could be compelled, in a legal or equitable proceeding, to accept a money satisfaction of such interest."],[0,"(g) Notwithstanding subsection (f) of this section, the trustee may sell property under subsection (b) or (c) of this section free and clear of any vested or contingent right in the nature of dower or curtesy."],[0,"(h) Notwithstanding subsection (f) of this section, the trustee may sell both the estate's interest, under subsection (b) or (c) of this section, and the interest of any co-owner in property in which the debtor had, at the time of the commencement of the case, an undivided interest as a tenant in common, joint tenant, or tenant by the entirety, only if—"],[1,"(1) partition in kind of such property among the estate and such co-owners is impracticable;"],[1,"(2) sale of the estate's undivided interest in such property would realize significantly less for the estate than sale of such property free of the interests of such co-owners;"],[1,"(3) the benefit to the estate of a sale of such property free of the interests of co-owners outweighs the detriment, if any, to such co-owners; and"],[1,"(4) such property is not used in the production, transmission, or distribution, for sale, of electric energy or of natural or synthetic gas for heat, light, or power."],[0,"(i) Before the consummation of a sale of property to which subsection (g) or (h) of this section applies, or of property of the estate that was community property of the debtor and the debtor's spouse immediately before the commencement of the case, the debtor's spouse, or a co-owner of such property, as the case may be, may purchase such property at the price at which such sale is to be consummated."],[0,"(j) After a sale of property to which subsection (g) or (h) of this section applies, the trustee shall distribute to the debtor's spouse or the co-owners of such property, as the case may be, and to the estate, the proceeds of such sale, less the costs and expenses, not including any compensation of the trustee, of such sale, according to the interests of such spouse or co-owners, and of the estate."],[0,"(k) At a sale under subsection (b) of this section of property that is subject to a lien that secures an allowed claim, unless the court for cause orders otherwise the holder of such claim may bid at such sale, and, if the holder of such claim purchases such property, such holder may offset such claim against the purchase price of such property."],[0,"(l) Subject to the provisions of section 365, the trustee may use, sell, or lease property under subsection (b) or (c) of this section, or a plan under chapter 11, 12, or 13 of this title may provide for the use, sale, or lease of property, notwithstanding any provision in a contract, a lease, or applicable law that is conditioned on the insolvency or financial condition of the debtor, on the commencement of a case under this title concerning the debtor, or on the appointment of or the taking possession by a trustee in a case under this title or a custodian, and that effects, or gives an option to effect, a forfeiture, modification, or termination of the debtor's interest in such property."],[0,"(m) The reversal or modification on appeal of an authorization under subsection (b) or (c) of this section of a sale or lease of property does not affect the validity of a sale or lease under such authorization to an entity that purchased or leased such property in good faith, whether or not such entity knew of the pendency of the appeal, unless such authorization and such sale or lease were stayed pending appeal."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/363?type=usc&year=mostrecent&link-type=html"},"by":{"1":"19, 22, 19, 22, 19, 22","2":"5, 5, 5"},"q":[{"src":"argument","who":"Mr. Goldblatt","text":"First, on the question what is the defense, Section 542 says expressly that the turnover power -- the turnover obligation applies to property that is -- it -- it says it is subject to Section 363(e), a section subject to Section 363, and subsection 363(e) provides that the -- the court -- that it is -- the property is not subject to the trustee's use if the credit -- if the debtor cannot provide adequate protection to the creditor."}]},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","by":{"1":"19, 22"}},{"t":"usc","label":"11 U.S.C. § 522","url":"https://www.law.cornell.edu/uscode/text/11/522","by":{"1":"19, 22"}},{"t":"usc","label":"11 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/11/542","subs":["(a)","(b)","(c)","(d)","(e)"],"stext":{"head":"§542. Turnover of property to the estate","paras":[[0,"(a) Except as provided in subsection (c) or (d) of this section, an entity, other than a custodian, in possession, custody, or control, during the case, of property that the trustee may use, sell, or lease under section 363 of this title, or that the debtor may exempt under section 522 of this title, shall deliver to the trustee, and account for, such property or the value of such property, unless such property is of inconsequential value or benefit to the estate."],[0,"(b) Except as provided in subsection (c) or (d) of this section, an entity that owes a debt that is property of the estate and that is matured, payable on demand, or payable on order, shall pay such debt to, or on the order of, the trustee, except to the extent that such debt may be offset under section 553 of this title against a claim against the debtor."],[0,"(c) Except as provided in section 362(a)(7) of this title, an entity that has neither actual notice nor actual knowledge of the commencement of the case concerning the debtor may transfer property of the estate, or pay a debt owing to the debtor, in good faith and other than in the manner specified in subsection (d) of this section, to an entity other than the trustee, with the same effect as to the entity making such transfer or payment as if the case under this title concerning the debtor had not been commenced."],[0,"(d) A life insurance company may transfer property of the estate or property of the debtor to such company in good faith, with the same effect with respect to such company as if the case under this title concerning the debtor had not been commenced, if such transfer is to pay a premium or to carry out a nonforfeiture insurance option, and is required to be made automatically, under a life insurance contract with such company that was entered into before the date of the filing of the petition and that is property of the estate."],[0,"(e) Subject to any applicable privilege, after notice and a hearing, the court may order an attorney, accountant, or other person that holds recorded information, including books, documents, records, and papers, relating to the debtor's property or financial affairs, to turn over or disclose such recorded information to the trustee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/542?type=usc&year=mostrecent&link-type=html"},"by":{"1":"20, 20, 20, 20, 20","2":"passim, 51, 47, 47, 37"},"q":[{"src":"brief","b":1,"text":"an entity, other than a custodian, in possession, custody, or control, during the case, of property that the trustee may use, sell, or lease under section 363 of this title, or that the debtor may exempt under section 522 of this title, shall deliver to the trustee, and account for, such property or the value of such property, unless such property is of inconsequential value or benefit to the estate.","cite":"11 U.S.C. 542(a)"},{"src":"brief","b":1,"text":"that the debtor may exempt under section 522.","cite":"11 U.S.C. 542(a)"},{"src":"brief","b":2,"text":"except to the extent that such debt may be offset under section 553 of this title against a claim against the debtor.","cite":"11 U.S.C. §542(b)"},{"src":"argument","who":"Mr. Goldblatt","text":"First, on the question what is the defense, Section 542 says expressly that the turnover power -- the turnover obligation applies to property that is -- it -- it says it is subject to Section 363(e), a section subject to Section 363, and subsection 363(e) provides that the -- the court -- that it is -- the property is not subject to the trustee's use if the credit -- if the debtor cannot provide adequate protection to the creditor."},{"src":"argument","who":"Mr. Goldblatt","text":"I -- I -- I think the answer to your question, Justice Breyer, with respect, is that the question of turnover is a subject of Section 542, and while that is a \"shall\" command, that provision doesn't contain injunctive language."},{"src":"argument","who":"Mr. Goldblatt","text":"We think that the -- that Section 542, the turnover provision, is where that work is done. And Section 542 has specific exceptions and defenses, and there is an established way in which it works."}]},{"t":"usc","label":"11 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/11/553","by":{"1":"20"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"1":"3, 4"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"1":"3"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"1":"5"}},{"t":"usc","label":"28 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/28/158","subs":["(d)"],"by":{"1":"5"}},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"1":"1"}},{"t":"case","label":"Alabama v. Bozeman","cite":"533 U.S. 146","y":2001,"id":"2000/00-492","sc":1,"by":{"2":"35"},"q":[{"src":"brief","b":2,"text":"[T]he word ‘shall’ is ordinarily the language of command.","cite":"533 U.S. 146, 153"}]},{"t":"case","label":"Aldy v. Valmet Paper Machinery","cite":"74 F.3d 72","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/74/72/","by":{"2":"26-27"}},{"t":"case","label":"Busic v. United States","cite":"446 U.S. 398","y":1980,"id":"1979/78-6020","sc":1,"by":{"2":"47"},"q":[{"src":"argument","who":"Mr. Wedoff","text":"That's -- that's completely true, but the point is that if there is any redundancy between the two statutes, the redundancy should be resolved, as the Busic case said, by harmonizing them."}]},{"t":"case","label":"Central Virginia Community College v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"by":{"2":"2, 4, 30"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"by":{"2":"33, 47"},"q":[{"src":"brief","b":2,"text":"[r]edundancies across statutes are not unusual events in drafting, and so long as there is no ‘positive repugnancy’ between two laws, a court must give effect to both.","cite":"503 U.S. 249, 253"}]},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"135 S. Ct. 2028","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2028/","sc":1,"by":{"2":"25, 37"}},{"t":"case","label":"Freytag v. Commissioner of Internal Revenue","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"by":{"2":"32"},"q":[{"src":"brief","b":2,"text":"the technical nature of the amendment... does not alter the wide-ranging effect of the statutory text[.]","cite":"501 U.S. 868, 875"}]},{"t":"case","label":"Hartford Underwriters Insurance Co. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"by":{"2":"31, 32, 45","3":"13"},"q":[{"src":"brief","b":2,"text":"[W]hile pre-Code practice, ‘informs [the Court’s] understanding of the language of the Code,’ it cannot overcome that language. It is a tool of construction, not an extratextual supplement.","cite":"530 U.S. at 10"}]},{"t":"case","label":"Helmers v. Anderson","cite":"156 F.2d 47","y":1946,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/156/47/","by":{"2":"27"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"by":{"2":"35"}},{"t":"case","label":"Kingdomware Technologies, Inc. v. United States","cite":"136 S. Ct. 1969","y":2016,"id":"2015/14-916","sc":1,"by":{"2":"35, 36"},"q":[{"src":"brief","b":2,"text":"Unlike the word ‘may,’ which implies discretion, the word ‘shall’ usually connotes a requirement.","cite":"136 S. Ct. at 1977"},{"src":"brief","b":2,"text":"it is generally clear that ‘shall’ imposes a mandatory duty.","cite":"136 S. Ct. at 1977"}]},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"by":{"2":"35"}},{"t":"case","label":"MidAtlantic National Bank v. New Jersey Department of Environmental Protection","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"by":{"2":"20, 48, 49"},"q":[{"src":"brief","b":2,"text":"‘one of the fundamental debtor protections provided by the bankruptcy laws.’","cite":"474 U.S. 494, 503"},{"src":"brief","b":2,"text":"one of the fundamental debtor protections.","cite":"474 U.S. at 503"}]},{"t":"case","label":"Miller v. Strahl","cite":"239 U.S. 426","y":1915,"id":"scdb/1915-006","sc":1,"by":{"2":"27"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"by":{"2":"2"}},{"t":"case","label":"Obduskey v. McCarthy & Holthus LLP","cite":"139 S. Ct. 1029","y":2019,"id":"2018/17-1307","sc":1,"by":{"2":"22"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"by":{"2":"25"}},{"t":"case","label":"Raleigh v. Illinois Department of Revenue","cite":"530 U.S. 15","y":2000,"id":"1999/99-387","sc":1,"by":{"2":"49"}},{"t":"case","label":"Ritzen Group, Inc. v. Jackson Masonry, LLC","cite":"2020 WL 201023","y":2020,"court":"U.S. Jan. 14","by":{"2":"5, 33"},"q":[{"src":"brief","b":2,"text":"[t]he stay bars … [the] exercise of control over the debtor’s property","cite":"2020 WL 201023"}]},{"t":"case","label":"Roell v. Withrow","cite":"538 U.S. 580","y":2003,"id":"2002/02-69","sc":1,"by":{"2":"42"}},{"t":"case","label":"Shea v. Kerry","cite":"961 F. Supp. 2d 17","y":2013,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/961/17/","by":{"2":"36, 37"},"q":[{"src":"brief","b":2,"text":"[n]othing is to be added to what the text states or reasonably implies (casus omissus pro omisso habendus est).’","cite":"961 F. Supp. 2d 17, 29 n.3"}]},{"t":"case","label":"Tennessee Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"by":{"2":"42"},"q":[{"src":"brief","b":2,"text":"abridg[ing], enlarg[ing], or modify[ing] any substantive right","cite":"541 U.S. 440, 453-54"}]},{"t":"case","label":"Union Bank v. Wolas","cite":"502 U.S. 151","y":1991,"id":"1991/90-1491","sc":1,"by":{"2":"23, 25, 31"}},{"t":"usc","label":"11 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/11/341","subs":["(a)"],"by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(a)(2)"],"stext":{"head":"§521. Debtor's duties","paras":[[0,"(a) The debtor shall—"],[1,"(1) file—"],[2,"(A) a list of creditors; and"],[2,"(B) unless the court orders otherwise—"],[3,"(i) a schedule of assets and liabilities;"],[3,"(ii) a schedule of current income and current expenditures;"],[3,"(iii) a statement of the debtor's financial affairs and, if section 342(b) applies, a certificate—"],[4,"(I) of an attorney whose name is indicated on the petition as the attorney for the debtor, or a bankruptcy petition preparer signing the petition under section 110(b)(1), indicating that such attorney or the bankruptcy petition preparer delivered to the debtor the notice required by section 342(b); or"],[4,"(II) if no attorney is so indicated, and no bankruptcy petition preparer signed the petition, of the debtor that such notice was received and read by the debtor;"],[3,"(iv) copies of all payment advices or other evidence of payment received within 60 days before the date of the filing of the petition, by the debtor from any employer of the debtor;"],[3,"(v) a statement of the amount of monthly net income, itemized to show how the amount is calculated; and"],[3,"(vi) a statement disclosing any reasonably anticipated increase in income or expenditures over the 12-month period following the date of the filing of the petition;"],[1,"(2) if an individual debtor's schedule of assets and liabilities includes debts which are secured by property of the estate—"],[2,"(A) within thirty days after the date of the filing of a petition under chapter 7 of this title or on or before the date of the meeting of creditors, whichever is earlier, or within such additional time as the court, for cause, within such period fixes, file with the clerk a statement of his intention with respect to the retention or surrender of such property and, if applicable, specifying that such property is claimed as exempt, that the debtor intends to redeem such property, or that the debtor intends to reaffirm debts secured by such property; and"],[2,"(B) within 30 days after the first date set for the meeting of creditors under section 341(a), or within such additional time as the court, for cause, within such 30-day period fixes, perform his intention with respect to such property, as specified by subparagraph (A) of this paragraph;"],[1,"except that nothing in subparagraphs (A) and (B) of this paragraph shall alter the debtor's or the trustee's rights with regard to such property under this title, except as provided in section 362(h);"],[1,"(3) if a trustee is serving in the case or an auditor is serving under section 586(f) of title 28, cooperate with the trustee as necessary to enable the trustee to perform the trustee's duties under this title;"],[1,"(4) if a trustee is serving in the case or an auditor is serving under section 586(f) of title 28, surrender to the trustee all property of the estate and any recorded information, including books, documents, records, and papers, relating to property of the estate, whether or not immunity is granted under section 344 of this title;"],[1,"(5) appear at the hearing required under section 524(d) of this title;"],[1,"(6) in a case under chapter 7 of this title in which the debtor is an individual, not retain possession of personal property as to which a creditor has an allowed claim for the purchase price secured in whole or in part by an interest in such personal property unless the debtor, not later than 45 days after the first meeting of creditors under section 341(a), either—"],[2,"(A) enters into an agreement with the creditor pursuant to section 524(c) with respect to the claim secured by such property; or"],[2,"(B) redeems such property from the security interest pursuant to section 722; and"],[1,"(7) unless a trustee is serving in the case, continue to perform the obligations required of the administrator (as defined in section 3 of the Employee Retirement Income Security Act of 1974) of an employee benefit plan if at the time of the commencement of the case the debtor (or any entity designated by the debtor) served as such administrator."],[0,"If the debtor fails to so act within the 45-day period referred to in paragraph (6), the stay under section 362(a) is terminated with respect to the personal property of the estate or of the debtor which is affected, such property shall no longer be property of the estate, and the creditor may take whatever action as to such property as is permitted by applicable nonbankruptcy law, unless the court determines on the motion of the trustee filed before the expiration of such 45-day period, and after notice and a hearing, that such property is of consequential value or benefit to the estate, orders appropriate adequate protection of the creditor's interest, and orders the debtor to deliver any collateral in the debtor's possession to the trustee."],[0,"(b) In addition to the requirements under subsection (a), a debtor who is an individual shall file with the court—"],[1,"(1) a certificate from the approved nonprofit budget and credit counseling agency that provided the debtor services under section 109(h) describing the services provided to the debtor; and"],[1,"(2) a copy of the debt repayment plan, if any, developed under section 109(h) through the approved nonprofit budget and credit counseling agency referred to in paragraph (1)."],[0,"(c) In addition to meeting the requirements under subsection (a), a debtor shall file with the court a record of any interest that a debtor has in an education individual retirement account (as defined in section 530(b)(1) of the Internal Revenue Code of 1986), an interest in an account in a qualified ABLE program (as defined in section 529A(b) of such Code,1 or under a qualified State tuition program (as defined in section 529(b)(1) of such Code)."],[0,"(d) If the debtor fails timely to take the action specified in subsection (a)(6) of this section, or in paragraphs (1) and (2) of section 362(h), with respect to property which a lessor or bailor owns and has leased, rented, or bailed to the debtor or as to which a creditor holds a security interest not otherwise voidable under section 522(f), 544, 545, 547, 548, or 549, nothing in this title shall prevent or limit the operation of a provision in the underlying lease or agreement that has the effect of placing the debtor in default under such lease or agreement by reason of the occurrence, pendency, or existence of a proceeding under this title or the insolvency of the debtor. Nothing in this subsection shall be deemed to justify limiting such a provision in any other circumstance."],[0,"(e)(1) If the debtor in a case under chapter 7 or 13 is an individual and if a creditor files with the court at any time a request to receive a copy of the petition, schedules, and statement of financial affairs filed by the debtor, then the court shall make such petition, such schedules, and such statement available to such creditor."],[0,"(2)(A) The debtor shall provide—"],[1,"(i) not later than 7 days before the date first set for the first meeting of creditors, to the trustee a copy of the Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such return) for the most recent tax year ending immediately before the commencement of the case and for which a Federal income tax return was filed; and"],[1,"(ii) at the same time the debtor complies with clause (i), a copy of such return (or if elected under clause (i), such transcript) to any creditor that timely requests such copy."],[0,"(B) If the debtor fails to comply with clause (i) or (ii) of subparagraph (A), the court shall dismiss the case unless the debtor demonstrates that the failure to so comply is due to circumstances beyond the control of the debtor."],[0,"(C) If a creditor requests a copy of such tax return or such transcript and if the debtor fails to provide a copy of such tax return or such transcript to such creditor at the time the debtor provides such tax return or such transcript to the trustee, then the court shall dismiss the case unless the debtor demonstrates that the failure to provide a copy of such tax return or such transcript is due to circumstances beyond the control of the debtor."],[0,"(3) If a creditor in a case under chapter 13 files with the court at any time a request to receive a copy of the plan filed by the debtor, then the court shall make available to such creditor a copy of the plan—"],[1,"(A) at a reasonable cost; and"],[1,"(B) not later than 7 days after such request is filed."],[0,"(f) At the request of the court, the United States trustee, or any party in interest in a case under chapter 7, 11, or 13, a debtor who is an individual shall file with the court—"],[1,"(1) at the same time filed with the taxing authority, a copy of each Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such tax return) with respect to each tax year of the debtor ending while the case is pending under such chapter;"],[1,"(2) at the same time filed with the taxing authority, each Federal income tax return required under applicable law (or at the election of the debtor, a transcript of such tax return) that had not been filed with such authority as of the date of the commencement of the case and that was subsequently filed for any tax year of the debtor ending in the 3-year period ending on the date of the commencement of the case;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/521?type=usc&year=mostrecent&link-type=html"},"by":{"2":"39, 21"},"q":[{"src":"argument","who":"Mr. Wedoff","text":"Section 521 imposes many obligations on the debtor, including the obligation to turn over property to the trustee. But the automatic stay enforces that obligation, and so it puts teeth into the 521 obligation."}]},{"t":"usc","label":"11 U.S.C. § 541","url":"https://www.law.cornell.edu/uscode/text/11/541","subs":["(a)","(a)(1)"],"by":{"2":"14, 19, 4, 19"},"q":[{"src":"brief","b":2,"text":"wherever located and by whomever held.","cite":"11 U.S.C. §541(a)(1)"}]},{"t":"usc","label":"11 U.S.C. § 544","url":"https://www.law.cornell.edu/uscode/text/11/544","subs":["(b)"],"by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 545","url":"https://www.law.cornell.edu/uscode/text/11/545","by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 547","url":"https://www.law.cornell.edu/uscode/text/11/547","subs":["(b)"],"by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 548","url":"https://www.law.cornell.edu/uscode/text/11/548","subs":["(a)"],"by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 549","url":"https://www.law.cornell.edu/uscode/text/11/549","subs":["(a)"],"by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 550","url":"https://www.law.cornell.edu/uscode/text/11/550","by":{"2":"39"}},{"t":"usc","label":"11 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/11/554","by":{"2":"21"}},{"t":"usc","label":"11 U.S.C. § 1107","url":"https://www.law.cornell.edu/uscode/text/11/1107","subs":["(a)"],"by":{"2":"5, 19, 34"}},{"t":"usc","label":"11 U.S.C. § 1203","url":"https://www.law.cornell.edu/uscode/text/11/1203","by":{"2":"5, 19, 34"}},{"t":"usc","label":"11 U.S.C. § 1207","url":"https://www.law.cornell.edu/uscode/text/11/1207","subs":["(b)"],"by":{"2":"5, 19, 34"}},{"t":"usc","label":"11 U.S.C. § 1303","url":"https://www.law.cornell.edu/uscode/text/11/1303","by":{"2":"1, 5, 19, 34"}},{"t":"usc","label":"11 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/11/1304","by":{"2":"5"}},{"t":"usc","label":"11 U.S.C. § 1306","url":"https://www.law.cornell.edu/uscode/text/11/1306","subs":["(b)"],"by":{"2":"1, 5, 19, 34"}},{"t":"usc","label":"11 U.S.C. § 1325","url":"https://www.law.cornell.edu/uscode/text/11/1325","subs":["(a)(5)(c)"],"by":{"2":"21"},"q":[{"src":"argument","who":"Mr. Wedoff","text":"Moreover, a debtor in Chapter 13 has the ability to allow the creditor to keep the property as satisfaction of the creditor's claim under Section 1325 --"}]},{"t":"usc","label":"28 U.S.C. § 2075","url":"https://www.law.cornell.edu/uscode/text/28/2075","by":{"2":"43"}},{"t":"case","label":"Ritzen Group, Inc. v. Jackson Masonry, LLC","cite":"140 S. Ct. 582","y":2020,"id":"2019/18-938","sc":1,"by":{"3":"8"},"q":[{"src":"brief","b":3,"text":"maintain[] the status quo and prevent[] dismemberment of the estate during the pendency of the bankruptcy case.","cite":"140 S. Ct. 582, 589"}]}]};